/**
 * Personalized license certificate: after paying, the player types the name to print; the art is
 * generated by an image model through OpenRouter (the parchment is the reference image), then the
 * wax seal is composited server-side so it always looks right. Two generations per license
 * (the model may misspell a name), a global hourly budget, one in flight per license.
 */
import { randomBytes } from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import sharp from "sharp";
import prisma from "../../core/database/prisma.js";
import { logger } from "../../core/logger/index.js";
import { slidingWindowAllow } from "../../core/http/middleware/distributedRateLimit.js";
import { mediaDiskDir, mediaPublicPath } from "../media/media.config.js";
import { AvatarError } from "./avatar.errors.js";

const log = logger.child("AvatarCertificate");

export const CERT_MAX_ATTEMPTS = 2;
export const CERT_GLOBAL_PER_HOUR = Number(process.env.AVATAR_CERT_GLOBAL_PER_HOUR || 30);
export const CERT_MEDIA_CATEGORY = "certificates";
const CERT_MODEL = process.env.AVATAR_CERT_MODEL || "bytedance-seed/seedream-5-0-flash";
const CERT_TIMEOUT_MS = 180_000;
/** A pending row older than this was lost (restart mid-generation) and may be retried. */
const STALE_PENDING_MS = 10 * 60_000;

export const CERT_LANGUAGES = ["pt-BR", "en", "es"] as const;
export type CertLanguage = (typeof CERT_LANGUAGES)[number];

/** Only short, fixed lines go to the model: long sentences came back with typos. */
const TEXTS: Record<CertLanguage, { title: string; validity: string }> = {
  "pt-BR": { title: "Certificado de Licença", validity: "Válido por 1 ano" },
  en: { title: "License Certificate", validity: "Valid for 1 year" },
  es: { title: "Certificado de Licencia", validity: "Válido por 1 año" },
};

/**
 * Letters (any script), digits, space and . ' _ - only, 2–24 chars. The name goes into the image
 * prompt, so nothing that could carry instructions or quotes is accepted.
 */
const NAME_RE = /^[\p{L}\p{N}][\p{L}\p{N} .'_-]{0,22}[\p{L}\p{N}.]$/u;

export function normalizeHolderName(raw: unknown): string | null {
  if (typeof raw !== "string") return null;
  // Line breaks, tabs and control characters are refused, not "fixed".
  if (/[\p{Cc}\p{Cf}\u2028\u2029]/u.test(raw)) return null;
  const name = raw.normalize("NFC").replace(/ {2,}/g, " ").trim();
  return NAME_RE.test(name) ? name : null;
}

export function resolveCertLanguage(v: unknown): CertLanguage {
  const s = String(v ?? "").toLowerCase();
  if (s.startsWith("pt")) return "pt-BR";
  if (s.startsWith("es")) return "es";
  return "en";
}

export function buildCertificatePrompt(name: string, lang: CertLanguage): string {
  const t = TEXTS[lang];
  return [
    "Turn this blank parchment into an elegant official certificate for a crypto-mining video game.",
    "Keep the parchment, its ornate border and the corner mining decorations exactly as they are.",
    `Layout (same as the site preview): starting about one quarter from the top, centered, the title "${t.title}" in a large bold classic serif (Cormorant Garamond style), dark brown ink, on two lines;`,
    `right below it, smaller, "${t.validity}" in the same serif.`,
    `At about 60% of the height, centered, on a thin horizontal signature line, the holder name "${name}" in large elegant script calligraphy (Great Vibes style), spelled exactly like that, letter by letter.`,
    "Do NOT draw any seal, stamp, badge, ribbon or wax; leave the bottom-right corner plain parchment. No other text, no logos, no watermark.",
  ].join(" ");
}

function artPath(file: string): string {
  const candidates = [path.join(process.cwd(), "client", "dist", "contract", file), path.join(process.cwd(), "client", "public", "contract", file)];
  const found = candidates.find((p) => fs.existsSync(p));
  if (!found) throw new Error(`CERT_ART_MISSING:${file}`);
  return found;
}

type ImageFetch = (url: string, init: RequestInit) => Promise<Response>;

/** Calls the OpenRouter Image API and returns the image bytes. Throws AvatarError on any failure. */
export async function generateCertificateImage(name: string, lang: CertLanguage, deps: { fetch?: ImageFetch; apiKey?: string } = {}): Promise<Buffer> {
  const apiKey = deps.apiKey ?? process.env.OPENROUTER_API_KEY;
  if (!apiKey) throw new AvatarError("AVATAR_CERT_NOT_CONFIGURED");
  const reference = await sharp(artPath("contract-parchment.webp")).jpeg({ quality: 85 }).toBuffer();
  const body = {
    model: CERT_MODEL,
    prompt: buildCertificatePrompt(name, lang),
    aspect_ratio: "3:4",
    resolution: "2K",
    n: 1,
    input_references: [{ type: "image_url", image_url: { url: `data:image/jpeg;base64,${reference.toString("base64")}` } }],
  };
  const doFetch = deps.fetch ?? fetch;
  let res: Response;
  try {
    res = await doFetch("https://openrouter.ai/api/v1/images", {
      method: "POST",
      headers: { Authorization: `Bearer ${apiKey}`, "Content-Type": "application/json", "X-Title": "BlockMiner" },
      body: JSON.stringify(body),
      signal: AbortSignal.timeout(CERT_TIMEOUT_MS),
    });
  } catch (err) {
    log.warn("AVATAR_CERT_PROVIDER_FAILED", { reason: "network", error: err instanceof Error ? err.name : "unknown" });
    throw new AvatarError("AVATAR_CERT_PROVIDER_FAILED");
  }
  if (!res.ok) {
    log.warn("AVATAR_CERT_PROVIDER_FAILED", { reason: "http", status: res.status });
    throw new AvatarError("AVATAR_CERT_PROVIDER_FAILED");
  }
  const json = (await res.json().catch(() => null)) as { data?: Array<{ b64_json?: string; url?: string }>; usage?: { cost?: number } } | null;
  const item = json?.data?.[0];
  let bytes: Buffer | null = null;
  if (item?.b64_json) bytes = Buffer.from(item.b64_json, "base64");
  else if (item?.url && /^https:\/\//.test(item.url)) {
    const img = await doFetch(item.url, { method: "GET", signal: AbortSignal.timeout(60_000) }).catch(() => null);
    if (img?.ok) bytes = Buffer.from(await img.arrayBuffer());
  }
  if (!bytes?.length) {
    log.warn("AVATAR_CERT_PROVIDER_FAILED", { reason: "empty" });
    throw new AvatarError("AVATAR_CERT_PROVIDER_FAILED");
  }
  log.info("avatar.certificate.generated", { model: CERT_MODEL, bytes: bytes.length, costUsd: json?.usage?.cost ?? null });
  return bytes;
}

/** Normalizes the model output and stamps the wax seal bottom-right. */
export async function finishCertificateImage(raw: Buffer): Promise<Buffer> {
  const W = 900, H = 1200, SEAL = 190;
  const base = await sharp(raw, { limitInputPixels: 40_000_000 }).resize(W, H, { fit: "fill" }).toBuffer();
  const seal = await sharp(artPath("contract-seal.webp")).resize(SEAL, SEAL).toBuffer();
  return sharp(base).composite([{ input: seal, left: W - SEAL - 95, top: H - SEAL - 85 }]).webp({ quality: 82 }).toBuffer();
}

export function certificateUrl(row: { status: string; path: string | null } | null | undefined): string | null {
  if (!row || row.status !== "ready" || !row.path || !/^[a-f0-9]{32}\.webp$/.test(row.path)) return null;
  return mediaPublicPath(CERT_MEDIA_CATEGORY, row.path);
}

export type CertificateView = {
  status: "none" | "pending" | "ready" | "failed";
  holderName: string | null;
  url: string | null;
  attemptsLeft: number;
  errorCode: string | null;
};

export function toCertificateView(row: { status: string; path: string | null; holderName: string; attempts: number; errorCode: string | null; updatedAt: Date } | null, now = Date.now()): CertificateView {
  if (!row) return { status: "none", holderName: null, url: null, attemptsLeft: CERT_MAX_ATTEMPTS, errorCode: null };
  const stale = row.status === "pending" && now - row.updatedAt.getTime() > STALE_PENDING_MS;
  const status = stale ? "failed" : (row.status as CertificateView["status"]);
  return {
    status,
    holderName: row.holderName,
    url: certificateUrl(row),
    attemptsLeft: Math.max(0, CERT_MAX_ATTEMPTS - row.attempts + (stale ? 1 : 0)),
    errorCode: stale ? "AVATAR_CERT_PROVIDER_FAILED" : row.errorCode,
  };
}

/** Latest license still in force for the user (the certificate belongs to it). */
async function currentLicense(userId: number, now: Date) {
  return prisma.avatarLicense.findFirst({ where: { userId, expiresAt: { gt: now } }, orderBy: { expiresAt: "desc" }, select: { id: true } });
}

export async function getCertificateView(userId: number, now = new Date()): Promise<CertificateView | null> {
  const lic = await currentLicense(userId, now);
  if (!lic) return null;
  const row = await prisma.avatarCertificate.findUnique({ where: { licenseId: lic.id } });
  return toCertificateView(row, now.getTime());
}

/**
 * Reserves an attempt (atomically) and starts the generation in the background. Returns at once;
 * the client polls GET /api/avatar until the certificate is ready or failed.
 */
export async function requestCertificate(
  userId: number,
  input: { name: unknown; language: unknown },
  deps: { generate?: typeof generateCertificateImage; now?: Date } = {},
): Promise<{ view: CertificateView; job: Promise<void> }> {
  const now = deps.now ?? new Date();
  const name = normalizeHolderName(input.name);
  if (!name) throw new AvatarError("AVATAR_CERT_NAME_INVALID");
  const lang = resolveCertLanguage(input.language);
  const lic = await currentLicense(userId, now);
  if (!lic) throw new AvatarError("AVATAR_LICENSE_REQUIRED");
  if (!process.env.OPENROUTER_API_KEY && !deps.generate) throw new AvatarError("AVATAR_CERT_NOT_CONFIGURED");

  const existing = await prisma.avatarCertificate.findUnique({ where: { licenseId: lic.id } });
  const view = toCertificateView(existing, now.getTime());
  if (view.status === "pending") throw new AvatarError("AVATAR_CERT_BUSY");
  if (view.attemptsLeft <= 0) throw new AvatarError("AVATAR_CERT_LIMIT_REACHED");

  const budget = await slidingWindowAllow({ dedupeKey: "global", windowMs: 3_600_000, max: CERT_GLOBAL_PER_HOUR, redisPrefix: "avatar:cert" });
  if (!budget.ok) throw new AvatarError("AVATAR_CERT_BUSY", { retryAfterSec: budget.retryAfterSec });

  // A pending row lost to a restart (stale) gives its attempt back.
  const stale = existing?.status === "pending";
  const attemptsUsed = existing ? existing.attempts - (stale ? 1 : 0) : 0;
  // Reserve: create the row, or move it back to pending only if nobody changed it since we read it.
  if (!existing) {
    await prisma.avatarCertificate.create({ data: { licenseId: lic.id, userId, holderName: name, language: lang, status: "pending", attempts: 1 } });
  } else {
    const r = await prisma.avatarCertificate.updateMany({
      where: { licenseId: lic.id, attempts: existing.attempts, updatedAt: existing.updatedAt },
      data: { holderName: name, language: lang, status: "pending", attempts: attemptsUsed + 1, errorCode: null },
    });
    if (r.count !== 1) throw new AvatarError("AVATAR_CERT_BUSY");
  }
  log.info("avatar.certificate.requested", { userId, licenseId: lic.id, attempt: attemptsUsed + 1, language: lang });

  const generate = deps.generate ?? generateCertificateImage;
  const job = (async () => {
    try {
      const raw = await generate(name, lang);
      const finished = await finishCertificateImage(raw);
      const file = `${randomBytes(16).toString("hex")}.webp`;
      await fs.promises.writeFile(path.join(mediaDiskDir(CERT_MEDIA_CATEGORY), file), finished, { flag: "wx" });
      const prev = existing?.path;
      await prisma.avatarCertificate.update({ where: { licenseId: lic.id }, data: { status: "ready", path: file, errorCode: null } });
      if (prev && /^[a-f0-9]{32}\.webp$/.test(prev)) await fs.promises.unlink(path.join(mediaDiskDir(CERT_MEDIA_CATEGORY), prev)).catch(() => undefined);
      log.info("avatar.certificate.ready", { userId, licenseId: lic.id });
    } catch (err) {
      const code = err instanceof AvatarError ? err.code : "AVATAR_CERT_PROVIDER_FAILED";
      if (!(err instanceof AvatarError)) log.error("AVATAR_CERT_JOB_FAILED", { userId, licenseId: lic.id, error: err instanceof Error ? err.message : String(err) });
      await prisma.avatarCertificate.update({ where: { licenseId: lic.id }, data: { status: "failed", errorCode: code } }).catch(() => undefined);
    }
  })();
  const fresh = await prisma.avatarCertificate.findUnique({ where: { licenseId: lic.id } });
  return { view: toCertificateView(fresh, now.getTime()), job };
}
